static PTE *get_leaf_pte(uintptr_t va, uintptr_t pgdir_pa, int create)
{
    PTE *pgdir = (PTE *)pa2kva(pgdir_pa);
    int vpn2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int vpn1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int vpn0 = (va >> VPN0_SHIFT) & VPN_MASK;

    if (!get_attribute(pgdir[vpn2], _PAGE_PRESENT)) {
        if (!create) {
            return NULL;
        }

        PTE *second_level_pgdir = alloc_pgdir_page();
        set_pfn(pgdir + vpn2, (uint64_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(pgdir + vpn2, _PAGE_PRESENT);
    }

    PTE *second_level_pgdir = (PTE *)pa2kva(get_pa(pgdir[vpn2]));
    if (!get_attribute(second_level_pgdir[vpn1], _PAGE_PRESENT)) {
        if (!create) {
            return NULL;
        }

        PTE *last_level_pgdir = alloc_pgdir_page();
        set_pfn(second_level_pgdir + vpn1,
                (uint64_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(second_level_pgdir + vpn1, _PAGE_PRESENT);
    }

    PTE *last_level_pgdir = (PTE *)pa2kva(get_pa(second_level_pgdir[vpn1]));
    return last_level_pgdir + vpn0;
}

static void map_leaf_page(PTE *pgtable, uintptr_t pa)
{
    *pgtable = 0;
    set_pfn(pgtable, pa >> NORMAL_PAGE_SHIFT);
    set_attribute(pgtable, _PAGE_PRESENT);
    set_attribute(pgtable, _PAGE_READ);
    set_attribute(pgtable, _PAGE_WRITE);
    set_attribute(pgtable, _PAGE_EXEC);
    set_attribute(pgtable, _PAGE_USER);
    set_attribute(pgtable, _PAGE_ACCESSED);
    set_attribute(pgtable, _PAGE_DIRTY);
}

