}

// returns pa
PTE* alloc_pgdir_page()
{
    int i;
    for(i = 0; i < PGDIR_PAGE_NUM; i++){
        if(pgdir_page[i].valid == 0){
            break;
        }
    }
    assert(i != PGDIR_PAGE_NUM);
    pgdir_page[i].valid = 1;
    PTE *ret = (PTE*)(FREE_PGDIR_ADDR + i * PAGE_SIZE);
    clear_pgdir((PTE*)pa2kva((uintptr_t)ret));
