int pa2num(uintptr_t pa)
{
    return (pa - USER_MEM_BEGIN) / PAGE_SIZE;
}
ptr_t num2pa(int num)
{
    return (USER_MEM_BEGIN + num * PAGE_SIZE);
}

// returns pa
ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
{
    int page_num = -1;
    for (int i = 0; i < USER_PAGE_NUM; i++) {
        if (user_page[i].valid == 0) {
            page_num = i;
            break;
        }
    }

    if (page_num == -1) {
        ptr_t victim = selete_page();
        write_to_sd(victim);
        page_num = pa2num(victim);
    }

    user_page[page_num].valid = 1;
    user_page[page_num].pin = pin;
    user_page[page_num].pgtable = pgtable;
    memset((void *)pa2kva(num2pa(page_num)), 0, PAGE_SIZE);
    return num2pa(page_num);
}

// baseAddr is pa
void free_user_page(ptr_t baseAddr)
{
    user_page[pa2num(baseAddr)].valid = 0;
    user_page[pa2num(baseAddr)].pin = 0;
    user_page[pa2num(baseAddr)].pgtable = NULL;
}

// returns pa
void *kmalloc(size_t size)
{
    // align 4
    ptr_t ret = ROUND(kernel_memCurr, 4);
    kernel_memCurr = ret + size;
    return (void*)ret;
}

// select a user page to write to disk (NRU), returns pa
ptr_t selete_page()
{
    ptr_t ret = 0;
    int best_class = 4;

    for (int i = 0; i < USER_PAGE_NUM; i++) {
        if (!user_page[i].valid || user_page[i].pin || user_page[i].pgtable == NULL) {
            continue;
        }

        PTE *pgtable = user_page[i].pgtable;
        if (!get_attribute(*pgtable, _PAGE_PRESENT)) {
            continue;
        }

        int accessed = get_attribute(*pgtable, _PAGE_ACCESSED);
        int dirty = get_attribute(*pgtable, _PAGE_DIRTY);
        int page_class = (accessed ? 2 : 0) + (dirty ? 1 : 0);

        if (page_class < best_class) {
            best_class = page_class;
            ret = num2pa(i);
            if (best_class == 0) {
                break;
            }
        }

        if (accessed) {
            clear_attribute(pgtable, _PAGE_ACCESSED);
        }
    }

    assert(ret != 0);
    return ret;
}

void write_to_sd(ptr_t pa)
{
    int slot = -1;
    for (int i = 0; i < DISK_PAGE_NUM; i++) {
        if (disk_page[i].valid == 0) {
            slot = i;
            break;
        }
    }

    assert(slot != -1);
    sbi_sd_write(pa, PAGE_SIZE / 512, SWAP_BEGIN + slot * (PAGE_SIZE / 512));

    PTE *pgtable = user_page[pa2num(pa)].pgtable;
    assert(pgtable != NULL);
    *pgtable = 0;
    set_pfn(pgtable, slot);
    set_attribute(pgtable, _PAGE_SOFT);
    disk_page[slot].valid = 1;
    free_user_page(pa);
    local_flush_tlb_all();
}

