void free_process_user_page(PTE* pgdir)
{
    if (pgdir == NULL || pgdir == (PTE *)PGDIR_PA) {
        return;
    }

    PTE *pgdir_kva = (PTE *)pa2kva((uintptr_t)pgdir);
    for (int vpn2 = 0; vpn2 < NUM_PTE_ENTRY; vpn2++) {
        if (vpn2 == 0x101 || !get_attribute(pgdir_kva[vpn2], _PAGE_PRESENT)) {
            continue;
        }

        PTE *second_level_pgdir =
            (PTE *)pa2kva(get_pa(pgdir_kva[vpn2]));
        for (int vpn1 = 0; vpn1 < NUM_PTE_ENTRY; vpn1++) {
            if (!get_attribute(second_level_pgdir[vpn1], _PAGE_PRESENT)) {
                continue;
            }

            PTE *last_level_pgdir =
                (PTE *)pa2kva(get_pa(second_level_pgdir[vpn1]));
            for (int vpn0 = 0; vpn0 < NUM_PTE_ENTRY; vpn0++) {
                PTE entry = last_level_pgdir[vpn0];
                if (get_attribute(entry, _PAGE_PRESENT)) {
                    uintptr_t pa = get_pa(entry);
                    int shm_slot = find_shm_slot(pa);
                    if (shm_slot >= 0) {
                        shm_page[shm_slot].count--;
                        if (shm_page[shm_slot].count == 0) {
                            free_user_page(pa);
                            shm_page[shm_slot].pa = 0;
                        }
                    } else {
                        free_user_page(pa);
                    }
                } else if (get_attribute(entry, _PAGE_SOFT)) {
                    int slot = get_pfn(entry);
                    if (slot >= 0 && slot < DISK_PAGE_NUM) {
                        disk_page[slot].valid = 0;
                    }
                }
                last_level_pgdir[vpn0] = 0;
            }

            free_pgdir_page(kva2pa((uintptr_t)last_level_pgdir));
            second_level_pgdir[vpn1] = 0;
        }

        free_pgdir_page(kva2pa((uintptr_t)second_level_pgdir));
        pgdir_kva[vpn2] = 0;
    }

    free_pgdir_page((uintptr_t)pgdir);
}

// pgdir is pa. if va is not mapped, then mapped it
uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
{
    uintptr_t page_va = ROUNDDOWN(va, PAGE_SIZE);
    PTE *pgtable = get_leaf_pte(page_va, pgdir, 1);
    assert(pgtable != NULL);

    if (get_attribute(*pgtable, _PAGE_PRESENT)) {
        set_attribute(pgtable, _PAGE_ACCESSED);
        set_attribute(pgtable, _PAGE_DIRTY);
    } else if (get_attribute(*pgtable, _PAGE_SOFT)) {
        int slot = get_pfn(*pgtable);
        ptr_t pa = alloc_user_page(0, pgtable);
        sbi_sd_read(pa, PAGE_SIZE / 512, SWAP_BEGIN + slot * (PAGE_SIZE / 512));
        disk_page[slot].valid = 0;
        map_leaf_page(pgtable, pa);
    } else {
        ptr_t pa = alloc_user_page(0, pgtable);
        map_leaf_page(pgtable, pa);
    }

    local_flush_tlb_page(page_va);
    return get_kva_of(va, pgdir);
}

uintptr_t shm_page_get(int key)
{
    int shm_id = key % SHM_PAGE_NUM;
    if (shm_id < 0) {
        shm_id += SHM_PAGE_NUM;
    }

    if (shm_page[shm_id].count == 0) {
        shm_page[shm_id].pa = alloc_user_page(1, NULL);
    }

    for (uintptr_t va = PAGE_SIZE; va < 0x10000lu; va += PAGE_SIZE) {
        PTE *pgtable = get_leaf_pte(va, (uintptr_t)current_running[cpu_id]->pgdir, 1);
        if (*pgtable == 0) {
            map_leaf_page(pgtable, shm_page[shm_id].pa);
            shm_page[shm_id].count++;
            local_flush_tlb_page(va);
            return va;
        }
    }

    return 0;
}

void shm_page_dt(uintptr_t addr)
{
    uintptr_t va = ROUNDDOWN(addr, PAGE_SIZE);
    if (va < PAGE_SIZE || va >= 0x10000lu) {
        return;
    }

    PTE *pgtable = get_leaf_pte(va, (uintptr_t)current_running[cpu_id]->pgdir, 0);
    if (pgtable == NULL || !get_attribute(*pgtable, _PAGE_PRESENT)) {
        return;
    }

    int shm_slot = find_shm_slot(get_pa(*pgtable));
    if (shm_slot < 0) {
        return;
    }

    shm_page[shm_slot].count--;
    if (shm_page[shm_slot].count == 0) {
        free_user_page(shm_page[shm_slot].pa);
        shm_page[shm_slot].pa = 0;
    }
    *pgtable = 0;
    local_flush_tlb_page(va);
}

void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
{
    uintptr_t va = ROUNDDOWN(stval, PAGE_SIZE);
    PTE *pgtable = get_leaf_pte(va, (uintptr_t)current_running[cpu_id]->pgdir, 1);
    assert(pgtable != NULL);

    if (get_attribute(*pgtable, _PAGE_PRESENT)) {
        set_attribute(pgtable, _PAGE_ACCESSED);
        if (cause == EXCC_STORE_PAGE_FAULT) {
            set_attribute(pgtable, _PAGE_DIRTY);
        }
    } else if (get_attribute(*pgtable, _PAGE_SOFT)) {
        int slot = get_pfn(*pgtable);
        ptr_t pa = alloc_user_page(0, pgtable);
        sbi_sd_read(pa, PAGE_SIZE / 512, SWAP_BEGIN + slot * (PAGE_SIZE / 512));
        disk_page[slot].valid = 0;
        map_leaf_page(pgtable, pa);
    } else {
        ptr_t pa = alloc_user_page(0, pgtable);
        map_leaf_page(pgtable, pa);
    }

    local_flush_tlb_page(va);
    if (cause == EXCC_INST_PAGE_FAULT) {
        local_flush_icache_all();
    }
}

